    // ---------- 单调性与补录 ----------

    @Test
    void addReading_backfillMustSatisfyBothNeighbors() throws Exception {
        register("eq-mono", 1000);
        addReading("eq-mono", "m1", 1, "r1", "2026-01-01T10:00:00Z", 100, 201);
