        // 合法补录：100 <= 200 <= 300
        addReading("eq-mono", "m3", 3, "r2", "2026-01-01T11:00:00Z", 200, 201);

        // 补录超过后邻（300）：即使不小于前邻也必须 422，不得仅与最新值比较
        addReading("eq-mono", "m4", 4, "r2x", "2026-01-01T11:30:00Z", 350, 422);
